"use client"

// Bollard UI — boolean-query-input · MIT licence · https://bollard-ui.vercel.app/components/boolean-query-input

import * as React from "react"
import { TextSearch, TriangleAlert, X } from "lucide-react"

import { cn } from "@/lib/utils"
import { lintQuery, parseQuery, queryParts, tokenizeQuery, type QueryIssue, type QueryIssueKind, type QueryPrecedence } from "./boolean-query"

export * from "./boolean-query"

/** Default messages. `{phrase}`, `{word}`, `{op}`, `{count}` are filled in. */
export const BOOLEAN_QUERY_MESSAGES: Record<QueryIssueKind, { message: string; fix?: string }> & Record<"readsAs" | "meant" | "useMeant" | "keep" | "dismiss" | "andFirst" | "leftToRight", string> = {
  "smart-quotes": { message: "Curly quotes pasted from a document aren't read as quotes.", fix: "Use straight quotes" },
  "unclosed-quote": { message: "This quote is never closed, so everything after it becomes one long phrase.", fix: "Close it after “{phrase}”" },
  brackets: { message: "Only ( ) group terms. [ ] and { } are searched as plain text.", fix: "Use ( )" },
  "stray-close": { message: "There's a ) with no ( before it.", fix: "Remove it" },
  "unclosed-open": { message: "A ( is never closed.", fix: "Close it at the end" },
  "empty-group": { message: "Empty brackets match nothing.", fix: "Remove them" },
  "lowercase-op": { message: "“{word}” in lowercase is searched as a word, not as {op}.", fix: "Make it {op}" },
  "dangling-op": { message: "{op} has nothing to join on one side, so it's ignored.", fix: "Remove {op}" },
  precedence: { message: "" },
  andFirst: "AND runs before OR, so it's grouped as highlighted.",
  leftToRight: "This search reads left to right, so it's grouped as highlighted.",
  meant: "Did you mean",
  useMeant: "Use this",
  keep: "Keep, add brackets",
  readsAs: "Reads as",
  dismiss: "Keep it as typed",
}

const fill = (s: string, d: Record<string, string>) => s.replace(/\{(\w+)\}/g, (m, k: string) => d[k] ?? m)
const field =
  "h-9 w-full min-w-0 rounded-md border bg-transparent px-3 text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 md:text-sm dark:bg-input/30 data-warning:border-amber-500 dark:data-warning:border-amber-400"
const fixClass =
  "inline-flex h-6 max-w-full items-center gap-1 rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

export interface BooleanQueryInputProps extends Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange"> {
  /** Visible label. */
  label?: string
  /** Controlled query. */
  value?: string
  /** Initial query when uncontrolled. */
  defaultValue?: string
  /** Called with the query on every change and fix. */
  onValueChange?: (value: string) => void
  /** How your search engine groups AND and OR without brackets. LinkedIn and most engines apply AND first. */
  precedence?: QueryPrecedence
  /** Called with the current issues once typing pauses, so a form can hold the search until they're fixed. */
  onIssuesChange?: (issues: QueryIssue[]) => void
  /** Pause in ms before warnings appear while typing. Leaving the field shows them at once. */
  delay?: number
  /** Override any message or label. */
  messages?: Partial<typeof BOOLEAN_QUERY_MESSAGES>
}

/**
 * A search box for boolean strings that catches the mistakes that silently
 * return the wrong people: AND/OR mixed without brackets (it shows how the
 * engine will group them and offers the grouping you probably meant), a quote
 * or bracket never closed, curly quotes, [ ] used as brackets, lowercase and/or
 * searched as words and operators with nothing on one side. Every fix is one tap.
 */
export function BooleanQueryInput({
  label = "Search",
  value,
  defaultValue = "",
  onValueChange,
  precedence = "and-first",
  onIssuesChange,
  delay = 600,
  messages,
  id,
  className,
  onBlur,
  ref,
  "aria-describedby": describedBy,
  ...props
}: BooleanQueryInputProps) {
  const t = { ...BOOLEAN_QUERY_MESSAGES, ...messages }
  const [inner, setInner] = React.useState(defaultValue)
  const [settled, setSettled] = React.useState(defaultValue)
  const [dismissed, setDismissed] = React.useState<string>()
  const inputRef = React.useRef<HTMLInputElement>(null)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const query = value ?? inner
  React.useImperativeHandle(ref, () => inputRef.current as HTMLInputElement)

  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(query), delay)
    return () => clearTimeout(timer)
  }, [query, delay])

  const issues = React.useMemo(() => lintQuery(settled, precedence), [settled, precedence])
  const issuesRef = React.useRef(onIssuesChange)
  React.useEffect(() => {
    issuesRef.current = onIssuesChange
  })
  React.useEffect(() => issuesRef.current?.(issues), [issues])

  const update = (next: string, settle = false) => {
    if (value === undefined) setInner(next)
    if (settle) setSettled(next)
    onValueChange?.(next)
  }
  const apply = (next: string) => {
    update(next, true)
    inputRef.current?.focus()
  }

  const ready = settled === query
  const visible = ready ? issues.filter((i) => `${i.kind}:${query}` !== dismissed) : []
  const issue = visible[0]
  const parts = React.useMemo(() => queryParts(parseQuery(tokenizeQuery(query), precedence)), [query, precedence])
  const showReadback = parts.some((p) => p.role !== "term" || p.broken)
  const copy = issue && issue.kind !== "precedence" ? t[issue.kind] : undefined

  return (
    <div data-slot="boolean-query-input" className={cn("grid w-full max-w-md gap-1.5", className)}>
      <style>{`@keyframes cui-boolean-query-input-pop{from{opacity:0;transform:scale(1.6)}}`}</style>
      <label htmlFor={inputId} className="w-fit text-sm font-medium">{label}</label>
      <input
        ref={inputRef}
        id={inputId}
        type="search"
        autoComplete="off"
        autoCorrect="off"
        spellCheck={false}
        value={query}
        onChange={(e) => update(e.target.value)}
        onBlur={(e) => {
          setSettled(query)
          onBlur?.(e)
        }}
        aria-describedby={[showReadback && `${inputId}-readback`, `${inputId}-status`, describedBy].filter(Boolean).join(" ")}
        data-warning={issue ? "" : undefined}
        className={field}
        {...props}
      />
      <div className="grid min-h-6 gap-1.5 text-xs">
        {/* Redrawn on every keystroke, so it stays out of the live region. */}
        {showReadback && (
          <div id={`${inputId}-readback`} className="flex flex-wrap items-baseline gap-x-1.5 gap-y-1 rounded-md border bg-muted/40 px-2.5 py-2">
            <span className="mr-0.5 inline-flex items-center gap-1 self-center text-muted-foreground">
              <TextSearch aria-hidden className="size-3.5" /> {t.readsAs}
            </span>
            <span className="font-mono text-[13px] leading-6 break-words">
              {parts.map((p, i) => (
                <React.Fragment key={i}>
                  {i > 0 && !(parts[i - 1].text === "(" && parts[i - 1].role === "paren") && !(p.role === "paren" && p.text === ")") && " "}
                  {p.role === "op" ? (
                    <span className={p.implied ? "text-[11px] text-muted-foreground/70" : "font-semibold text-sky-700 dark:text-sky-400"}>{p.text}</span>
                  ) : p.role === "paren" ? (
                    <span
                      className={cn(
                        p.implied
                          ? "inline-block rounded-sm bg-amber-300/50 px-px font-semibold text-amber-900 motion-safe:animate-[cui-boolean-query-input-pop_300ms_ease-out] dark:bg-amber-400/25 dark:text-amber-200"
                          : "text-muted-foreground"
                      )}
                    >
                      {p.text}
                    </span>
                  ) : (
                    <span className={cn(p.broken && "underline decoration-red-500 decoration-wavy underline-offset-4")}>{p.text}</span>
                  )}
                </React.Fragment>
              ))}
            </span>
          </div>
        )}
        <div id={`${inputId}-status`} aria-live="polite" className="grid gap-1.5">
        {issue && (
          <p className="flex gap-1.5 text-amber-700 dark:text-amber-400">
            <span className="flex h-6 shrink-0 items-center"><TriangleAlert aria-hidden className="size-3.5" /></span>
            <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
              {issue.kind === "precedence" ? (
                <>
                  <span className="py-1">
                    {precedence === "and-first" ? t.andFirst : t.leftToRight}
                    <span className="sr-only"> ({issue.detail.engine})</span> {t.meant}{" "}
                    <code className="rounded-sm bg-amber-500/10 px-1 font-mono text-amber-900 dark:text-amber-200">{issue.detail.meant}</code>?
                  </span>
                  <button type="button" onClick={() => apply(issue.fix!)} aria-label={`${t.useMeant}: ${issue.detail.meant}`} className={fixClass}>{t.useMeant}</button>
                  <button type="button" onClick={() => apply(issue.keep!)} aria-label={`${t.keep}: ${issue.keep}`} className={fixClass}>{t.keep}</button>
                </>
              ) : (
                <>
                  <span className="py-1">{fill(copy!.message, issue.detail)}</span>
                  {issue.fix !== undefined && copy?.fix && (
                    <button type="button" onClick={() => apply(issue.fix!)} className={fixClass}>
                      <span className="truncate">{fill(copy.fix, issue.detail)}</span>
                    </button>
                  )}
                  {issue.kind === "lowercase-op" && (
                    <button
                      type="button"
                      onClick={() => setDismissed(`${issue.kind}:${query}`)}
                      aria-label={t.dismiss}
                      title={t.dismiss}
                      className="grid size-6 place-items-center rounded-md transition-colors hover:bg-amber-500/10 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
                    >
                      <X aria-hidden className="size-3.5" />
                    </button>
                  )}
                </>
              )}
            </span>
          </p>
        )}
        </div>
      </div>
    </div>
  )
}

// Bollard UI — boolean-query-input · MIT licence · https://bollard-ui.vercel.app/components/boolean-query-input

/** Pure tokenizer, parser and linter for boolean search strings (LinkedIn, ATS, job boards). No React. */

export type BooleanOperator = "AND" | "OR" | "NOT"
/** How the search engine groups AND and OR when there are no brackets. Most engines (LinkedIn, Bing) bind AND first. */
export type QueryPrecedence = "and-first" | "left-to-right"

export type QueryToken =
  | { type: "term"; text: string; start: number; end: number; quoted: boolean; closed: boolean }
  | { type: "op"; op: BooleanOperator; start: number; end: number }
  | { type: "open"; start: number; end: number }
  | { type: "close"; start: number; end: number }

export type QueryNode =
  | { kind: "term"; text: string; closed: boolean }
  | { kind: "group"; child: QueryNode | null }
  | { kind: "not"; child: QueryNode }
  | { kind: "and"; children: QueryNode[]; joins: ("AND" | "")[] }
  | { kind: "or"; children: QueryNode[] }

/** One piece of a readback. `implied` marks brackets and ANDs the engine adds that the user never typed. */
export interface QueryPart {
  text: string
  role: "term" | "op" | "paren"
  implied?: boolean
  broken?: boolean
}

export type QueryIssueKind =
  | "smart-quotes" | "unclosed-quote" | "brackets" | "stray-close" | "unclosed-open"
  | "empty-group" | "lowercase-op" | "dangling-op" | "precedence"

export interface QueryIssue {
  kind: QueryIssueKind
  /** Values for the message template. */
  detail: Record<string, string>
  /** The fixed query, when one tap can fix it. */
  fix?: string
  /** For "precedence": the query with the engine's own grouping written out. */
  keep?: string
}

const QUOTE = /["“”„]/
const SMART = /[“”„]/g

export function tokenizeQuery(query: string): QueryToken[] {
  const tokens: QueryToken[] = []
  let i = 0
  while (i < query.length) {
    const ch = query[i]
    if (/\s/.test(ch)) i++
    else if (ch === "(" || ch === ")") tokens.push(ch === "(" ? { type: "open", start: i, end: ++i } : { type: "close", start: i, end: ++i })
    else if (QUOTE.test(ch)) {
      let j = i + 1
      while (j < query.length && !QUOTE.test(query[j])) j++
      const closed = j < query.length
      const end = closed ? j + 1 : query.length
      tokens.push({ type: "term", text: query.slice(i, end), start: i, end, quoted: true, closed })
      i = end
    } else {
      let j = i
      while (j < query.length && !/[\s()"“”„]/.test(query[j])) j++
      const text = query.slice(i, j)
      if (text === "AND" || text === "OR" || text === "NOT") tokens.push({ type: "op", op: text, start: i, end: j })
      else tokens.push({ type: "term", text, start: i, end: j, quoted: false, closed: true })
      i = j
    }
  }
  return tokens
}

type Item = { t: "operand"; node: QueryNode } | { t: "op"; op: BooleanOperator | "" }

/** Groups tokens by bracket level (tolerating stray brackets), then parses each level with the chosen precedence. */
export function parseQuery(tokens: QueryToken[], mode: QueryPrecedence | "or-first"): QueryNode | null {
  let i = 0
  const level = (nested: boolean): QueryNode | null => {
    const raw: Item[] = []
    while (i < tokens.length) {
      const tok = tokens[i++]
      if (tok.type === "close") {
        if (nested) return build(raw, mode)
        continue // a stray ")" at the top level is ignored, as engines do
      }
      if (tok.type === "open") raw.push({ t: "operand", node: { kind: "group", child: level(true) } })
      else if (tok.type === "op") raw.push({ t: "op", op: tok.op })
      else raw.push({ t: "operand", node: { kind: "term", text: tok.text, closed: tok.closed } })
    }
    return build(raw, mode)
  }
  return level(false)
}

function build(raw: Item[], mode: QueryPrecedence | "or-first"): QueryNode | null {
  // Drop dangling AND/OR and add the implicit AND between neighbours ("java remote", "java NOT php").
  const items: Item[] = []
  for (const item of raw) {
    const prev = items[items.length - 1]
    if (item.t === "op" && item.op !== "NOT") {
      if (prev?.t === "operand") items.push(item)
      else if (prev?.t === "op" && prev.op !== "NOT") items[items.length - 1] = item
      continue
    }
    if (prev?.t === "operand") items.push({ t: "op", op: "" })
    items.push(item)
  }
  while (items.length && items[items.length - 1].t === "op") items.pop()
  if (!items.length) return null

  if (mode === "left-to-right") {
    let pos = 0
    const unit = (): QueryNode => {
      const item = items[pos++]
      return item.t === "op" ? { kind: "not", child: unit() } : item.node
    }
    let acc = unit()
    while (pos < items.length) {
      const op = (items[pos++] as { op: BooleanOperator | "" }).op
      acc = op === "OR" ? join("or", [acc, unit()]) : join("and", [acc, unit()], [op as "AND" | ""])
    }
    return acc
  }

  // Split on the loosest operator, then the tighter one inside each part.
  const [outer, inner] = mode === "and-first" ? (["OR", "AND"] as const) : (["AND", "OR"] as const)
  const split = (list: Item[], on: "AND" | "OR") => {
    const parts: Item[][] = [[]]
    const joins: ("AND" | "")[] = []
    for (const item of list) {
      const isJoin = item.t === "op" && (on === "OR" ? item.op === "OR" : item.op === "AND" || item.op === "")
      if (isJoin) {
        parts.push([])
        joins.push(item.op as "AND" | "")
      } else parts[parts.length - 1].push(item)
    }
    return { parts, joins }
  }
  const units = (list: Item[]): QueryNode => {
    // In or-first reading, a leading NOT takes the whole OR list after it: NOT (junior OR intern).
    if (mode === "or-first" && list[0]?.t === "op" && list.length > 2) return { kind: "not", child: units(list.slice(1)) }
    const { parts } = split(list, inner === "OR" ? "OR" : "AND")
    const nodes = parts.map(unaries)
    return inner === "OR" ? join("or", nodes) : join("and", nodes, split(list, "AND").joins)
  }
  const unaries = (list: Item[]): QueryNode => {
    const [first, ...rest] = list
    return first.t === "op" ? { kind: "not", child: unaries(rest) } : first.node
  }
  const { parts, joins } = split(items, outer)
  const nodes = parts.map(units)
  return outer === "OR" ? join("or", nodes) : join("and", nodes, joins)
}

function join(kind: "and" | "or", nodes: QueryNode[], joins: ("AND" | "")[] = []): QueryNode {
  if (nodes.length === 1) return nodes[0]
  if (kind === "or") return { kind, children: nodes.flatMap((n) => (n.kind === "or" ? n.children : [n])) }
  const children: QueryNode[] = []
  const all: ("AND" | "")[] = []
  nodes.forEach((n, idx) => {
    if (idx) all.push(joins[idx - 1] ?? "AND")
    if (n.kind === "and") {
      children.push(...n.children)
      all.push(...n.joins)
    } else children.push(n)
  })
  return { kind, children, joins: all }
}

/** The query as parts, with the brackets the engine implies added and marked. */
export function queryParts(node: QueryNode | null): QueryPart[] {
  if (!node) return []
  const wrap = (child: QueryNode, parent: QueryNode["kind"]): QueryPart[] => {
    const inner = queryParts(child)
    // A NOT inside an OR list is bracketed too, since "NOT a OR b" is the classic misread.
    const needs = ((child.kind === "and" || child.kind === "or") && child.kind !== parent) || (child.kind === "not" && parent === "or")
    return needs ? [{ text: "(", role: "paren", implied: true }, ...inner, { text: ")", role: "paren", implied: true }] : inner
  }
  switch (node.kind) {
    case "term":
      return [{ text: node.text, role: "term", broken: !node.closed }]
    case "group":
      return [{ text: "(", role: "paren" }, ...queryParts(node.child), { text: ")", role: "paren" }]
    case "not":
      return [{ text: "NOT", role: "op" }, ...wrap(node.child, "not")]
    case "or":
      return node.children.flatMap((c, idx) => [...(idx ? [{ text: "OR", role: "op" } as QueryPart] : []), ...wrap(c, "or")])
    case "and":
      return node.children.flatMap((c, idx) => [
        ...(idx ? [{ text: "AND", role: "op", implied: node.joins[idx - 1] === "" } as QueryPart] : []),
        ...wrap(c, "and"),
      ])
  }
}

/** Writes parts back as a query string. Implied ANDs stay implicit; implied brackets are written out. */
export function partsToQuery(parts: QueryPart[]): string {
  let out = ""
  parts.forEach((p, idx) => {
    if (p.role === "op" && p.implied) return
    const prev = parts[idx - 1]
    if (out && !(prev?.text === "(" && prev.role === "paren") && !(p.text === ")" && p.role === "paren")) out += " "
    out += p.text
  })
  return out
}

const replaceAt = (s: string, start: number, end: number, text: string) => (s.slice(0, start) + text + s.slice(end)).replace(/\s{2,}/g, " ").trim()

/** Every mistake in the query, most fundamental first. Fix one and the next one shows. */
export function lintQuery(query: string, precedence: QueryPrecedence = "and-first"): QueryIssue[] {
  const issues: QueryIssue[] = []
  const tokens = tokenizeQuery(query)
  if (/[“”„]/.test(query)) issues.push({ kind: "smart-quotes", detail: {}, fix: query.replace(SMART, '"') })

  const open = tokens.find((t) => t.type === "term" && !t.closed)
  if (open) {
    // Close the phrase where it most likely ends: before the next operator or bracket.
    const rest = query.slice(open.start + 1)
    const stop = rest.search(/\s+(AND|OR|NOT)\s|\s*\)/)
    const at = stop < 0 ? query.trimEnd().length : open.start + 1 + stop
    const phrase = query.slice(open.start + 1, at).trim()
    issues.push({ kind: "unclosed-quote", detail: { phrase }, fix: query.slice(0, at).trimEnd() + '"' + query.slice(at) })
  }

  const outside = tokens.filter((t) => t.type === "term" && !t.quoted).map((t) => (t as { text: string }).text).join(" ")
  if (/[[\]{}]/.test(outside)) {
    let inQuote = false
    const fix = [...query].map((c) => (QUOTE.test(c) ? ((inQuote = !inQuote), c) : inQuote ? c : c === "[" || c === "{" ? "(" : c === "]" || c === "}" ? ")" : c)).join("")
    issues.push({ kind: "brackets", detail: {}, fix })
  }

  let depth = 0
  const opens: QueryToken[] = []
  for (const tok of tokens) {
    if (tok.type === "open") opens.push(tok), depth++
    else if (tok.type === "close") {
      if (depth === 0) {
        issues.push({ kind: "stray-close", detail: {}, fix: replaceAt(query, tok.start, tok.end, "") })
        break
      }
      depth--, opens.pop()
    }
  }
  if (depth > 0) issues.push({ kind: "unclosed-open", detail: { count: String(depth) }, fix: query.trimEnd() + ")".repeat(depth) })

  tokens.forEach((tok, idx) => {
    const next = tokens[idx + 1]
    if (tok.type === "open" && next?.type === "close" && !issues.some((i) => i.kind === "empty-group"))
      issues.push({ kind: "empty-group", detail: {}, fix: replaceAt(query, tok.start, next.end, "") })
  })

  const lower = tokens.filter(
    (t, idx): t is Extract<QueryToken, { type: "term" }> =>
      t.type === "term" && !t.quoted && /^(and|or|not)$/i.test(t.text) && t.text !== t.text.toUpperCase() && idx > 0 && idx < tokens.length - 1
  )
  if (lower.length) {
    const fix = lower.reduceRight((s, t) => s.slice(0, t.start) + t.text.toUpperCase() + s.slice(t.end), query)
    issues.push({ kind: "lowercase-op", detail: { word: lower[0].text, op: lower[0].text.toUpperCase(), count: String(lower.length) }, fix })
  }

  const dangling = tokens.find((t, idx) => {
    if (t.type !== "op") return false
    const prev = tokens[idx - 1]
    const next = tokens[idx + 1]
    const noLeft = t.op !== "NOT" && (!prev || prev.type === "open" || prev.type === "op")
    const noRight = !next || next.type === "close" || (next.type === "op" && next.op !== "NOT")
    return noLeft || noRight
  })
  if (dangling?.type === "op") issues.push({ kind: "dangling-op", detail: { op: dangling.op }, fix: replaceAt(query, dangling.start, dangling.end, "") })

  // Grouping is only worth explaining once the query is structurally sound; lowercase words may be intended.
  if (issues.every((i) => i.kind === "lowercase-op")) {
    const engine = partsToQuery(queryParts(parseQuery(tokens, precedence)))
    const meant = partsToQuery(queryParts(parseQuery(tokens, "or-first")))
    if (engine !== meant) issues.push({ kind: "precedence", detail: { engine, meant }, fix: meant, keep: engine })
  }
  return issues
}
